function diffBaselines(a, b) {
  const added = Object.keys(b).filter((k) => !(k in a)).sort();
  const removed = Object.keys(a).filter((k) => !(k in b)).sort();
  const changed = Object.keys(a).filter((k) => k in b && a[k] !== b[k]).sort().map((item) => ({ item, from: a[item], to: b[item] }));
  return { added, removed, changed };
}

function sameTestedConfiguration(log, baseline) {
  return Object.entries(log).every(([k, v]) => k in baseline && baseline[k] === v);
}
